161	        return this.householdSize;
162	    }
163	
164	    public void setHouseholdSize(Integer householdSize) {
165	        this.householdSize = householdSize;
166	    }
167	
168	    /**
169	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
170	     */
171	    public String getDisplayName() {
172	        return this.getLastName() + ", " + this.getFirstName();
173	    }
174	
175	    /**
176	     * The owner's initials: the upper-cased first letters of firstName and lastName,
177	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
178	     */
179	    public String getInitials() {
180	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
181	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
182	    }
183	
184	    /**
185	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
186	     * last two digits of the registrationDate year, e.g. {@code 'LON-SMI-0007-M26'}.
187	     */
188	    public String getMembershipNumber() {
189	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
190	    }
191	
192	    /**
193	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
194	     * contained in {@code value}. Reading the digits right to left, every second one is
195	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
196	     * digits are summed, and the check digit is the amount that must be added to that sum to
197	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
198	     * the digit is taken over exactly the digits the string carries.
199	     */
200	    private static int luhnCheckDigit(String value) {
201	        int sum = 0;
202	        boolean doubling = true;
203	        for (int i = value.length() - 1; i >= 0; i--) {
204	            char c = value.charAt(i);
205	            if (c < '0' || c > '9') {
206	                continue;
207	            }
208	            int digit = c - '0';
209	            if (doubling) {
210	                digit *= 2;
211	                if (digit > 9) {
212	                    digit -= 9;
213	                }
214	            }
215	            sum += digit;
216	            doubling = !doubling;
217	        }
218	        return (10 - (sum % 10)) % 10;
219	    }
220	
221	    /** Fixed city-to-region table used to derive an owner's locality. */
222	    private static final Map<String, String> CITY_REGION = Map.of(
223	        "Sydney", "NSW",
224	        "Melbourne", "VIC",
225	        "Brisbane", "QLD");
226	
227	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
228	    public static final String UNKNOWN_REGION = "UNKNOWN";
229	
230	    /**
231	     * The canonical region for a city, derived from the fixed city-to-region table
232	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
233	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
234	     * source of the city-to-region mapping, shared by every rule that is keyed by
235	     * region so the mapping is never re-derived elsewhere.
236	     */
237	    public static String regionOf(String city) {
238	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
239	    }
240	
241	    /**
242	     * The owner's locality. The postcode is preferred: when it falls within a known
243	     * {@linkplain #REGION_POSTCODE_RANGE region postcode range} that region is returned,
244	     * which disambiguates cities that share a name. Only when the postcode is absent or in
245	     * no known range does this fall back to the {@linkplain #regionOf(String) city-to-region
246	     * table}, yielding {@link #UNKNOWN_REGION} when the city has no known region.
247	     */
248	    public String getLocality() {
249	        String byPostcode = regionOfPostcode(this.postcode);
250	        return byPostcode != null ? byPostcode : regionOf(this.city);
251	    }
252	
253	    /**
254	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
255	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
256	     * no known range.
257	     */
258	    private static String regionOfPostcode(String postcode) {
259	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
260	            return null;
261	        }
262	        int value = Integer.parseInt(postcode);
263	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
264	            int[] range = entry.getValue();
265	            if (value >= range[0] && value <= range[1]) {
266	                return entry.getKey();
267	            }
268	        }
269	        return null;
270	    }
271	
272	    /**
273	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
274	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
275	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
276	     */
277	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
278	        "NSW", new int[] {2000, 2099},
279	        "VIC", new int[] {3000, 3099},
280	        "QLD", new int[] {4000, 4099});
281	
282	    /**
283	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
284	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
285	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
286	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
287	     * city with no known region accepts any 4-digit postcode.
288	     */
289	    public boolean isPostcodeValid() {
290	        if (this.postcode == null) {
291	            return true;
292	        }
293	        if (!this.postcode.matches("[0-9]{4}")) {
294	            return false;
295	        }
296	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
297	        if (range == null) {
298	            return true;
299	        }
300	        int value = Integer.parseInt(this.postcode);
301	        return value >= range[0] && value <= range[1];
302	    }
303	
304	    /**
305	     * The owner's membership level, a number from 1 to 3 determined on creation: it starts at 1,
306	     * gains 1 when an email is present, gains 1 when namesakeCount is 0, and is capped at 3.
307	     * Level 4 is reserved for tenure.
308	     */
309	    public Integer getMembershipLevel() {
310	        int level = 1;
311	        if (this.email != null && !this.email.isEmpty()) {
312	            level++;
313	        }
314	        if (this.namesakeCount != null && this.namesakeCount == 0) {
315	            level++;
316	        }
317	        return Math.min(level, 3);
318	    }
319	
320	    /**
321	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
322	     * otherwise {@code 'PHONE'}.
323	     */
324	    public String getContactPreference() {
325	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
326	    }
327	
328	    /**
329	     * The owner's identity key: the single derived value used for duplicate detection.
330	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
331	     * empty string when absent) and the householdId (or the empty string when the owner
332	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
333	     * Two owners are duplicates only when their whole identity keys are equal.
334	     */
335	    public String getIdentityKey() {
336	        String telephonePart = this.telephone == null ? "" : this.telephone;
337	        String emailPart = this.email == null ? "" : this.email;
338	        String householdPart = this.householdId == null ? "" : this.householdId;
339	        return telephonePart + "|" + emailPart + "|" + householdPart;
340	    }
341	
342	    protected Set<Pet> getPetsInternal() {
343	        if (this.pets == null) {
344	            this.pets = new HashSet<>();
345	        }
346	        return this.pets;
347	    }
348	
349	    protected void setPetsInternal(Set<Pet> pets) {
350	        this.pets = pets;
351	    }
352	
353	    public List<Pet> getPets() {
354	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
355	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
356	        return Collections.unmodifiableList(sortedPets);
357	    }
358	
359	    public void setPets(List<Pet> pets) {
360	        this.pets = new HashSet<>(pets);
361	    }
362	
363	    public void addPet(Pet pet) {
364	        getPetsInternal().add(pet);
365	        pet.setOwner(this);
366	    }
367	
368	    /**
369	     * Return the Pet with the given name, or null if none found for this Owner.
370	     *
371	     * @param name to test
372	     * @return true if pet name is already in use
373	     */
374	    public Pet getPet(String name) {
375	        return getPet(name, false);
376	    }
377	
378	    /**
379	     * Return the Pet with the given name, or null if none found for this Owner.
380	     *
381	     * @param name to test
382	     * @return true if pet name is already in use
383	     */
384	    public Pet getPet(String name, boolean ignoreNew) {
385	        name = name.toLowerCase();
386	        for (Pet pet : getPetsInternal()) {
387	            if (!ignoreNew || !pet.isNew()) {
388	                String compName = pet.getName();
389	                compName = compName.toLowerCase();
390	                if (compName.equals(name)) {
391	                    return pet;
392	                }
393	            }
394	        }
395	        return null;
396	    }
397	
398	    public Pet getPet(Integer petId) {
399	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
400	    }
401	
402	    @Override
403	    public String toString() {
404	        return new ToStringCreator(this)
405	
406	            .append("id", this.getId())
407	            .append("new", this.isNew())
408	            .append("lastName", this.getLastName())
409	            .append("firstName", this.getFirstName())
410	            .append("address", this.address)
411	            .append("city", this.city)
412	            .append("telephone", this.telephone)
413	            .append("email", this.email)
414	            .toString();
415	    }
416	}
